const b = $input.first().json.body || $input.first().json;
const dv = (b.conversation_initiation_client_data && b.conversation_initiation_client_data.dynamic_variables) || b.dynamic_variables || b.dynamicVariables || {};
const turns = Array.isArray(b.transcript) ? b.transcript : (Array.isArray(b.transcription) ? b.transcription : []);
let text = turns
  .map(t => ({ who: (t.role || t.speaker) === 'agent' ? 'Агент' : 'Клієнт', msg: String(t.message ?? t.text ?? '').trim() }))
  .filter(t => t.msg && t.msg !== '...')
  .map(t => t.who + ': ' + t.msg).join('\n');
if (!text) text = String(b.transcriptText || b.transcript_text || (typeof b.transcript === 'string' ? b.transcript : '') || '');
const phone = String(dv.phone_number || dv.system__caller_id || dv.system__called_number || b.phone || b.clientPhone || '').replace(/[^+\d]/g, '');
return [{ json: {
  conversation_id: b.conversation_id || b.callId || b.id || dv.system__conversation_id || ('call_' + Date.now()),
  lead_id: dv.lead_id || '',
  phone,
  name: dv.name || '',
  company: dv.company || '',
  duration: (b.metadata && b.metadata.call_duration_secs) ?? b.duration ?? dv.system__call_duration_secs ?? null,
  engine_summary: (b.analysis && b.analysis.transcript_summary) || '',
  call_successful: (b.analysis && b.analysis.call_successful) || b.callSuccessful || '',
  transcript: text,
  client_turns: (text.match(/^Клієнт:/gm) || []).length
} }];

