const r = $input.first().json.output;
const c = $('Нормалізація дзвінка').first().json;
const s = ['budget_score','authority_score','need_score','timeline_score'].map(k => Number(r[k]) || 0);
const score = s.reduce((a, b) => a + b, 0);
const status = score >= 70 ? 'Pre-Qualified' : score >= 40 ? 'Contact in Future' : 'Not Qualified';
const bant = { budget: r.budget, authority: r.authority, need: r.need, timeline: r.timeline, leads_per_month: r.leads_per_month ?? null, score, budget_score: s[0], authority_score: s[1], need_score: s[2], timeline_score: s[3], callback_time: r.callback_time || '', channel: 'voice', conversation_id: c.conversation_id };
const parts = String(r.client_name || c.name || '').trim().split(/\s+/).filter(Boolean);
return [{ json: {
  ...c,
  score, status,
  bant_confirmed: s.filter(x => x >= 15).length,
  score_comment: `B=${s[0]} (${r.budget}) · A=${s[1]} (${r.authority}) · N=${s[2]} (${r.need}) · T=${s[3]} (${r.timeline}) = ${score}`.slice(0, 1990),
  objections: String(r.objections || 'немає').slice(0, 250),
  next_action: String(r.next_action || '').slice(0, 250),
  description: (r.summary + '\n\nBANT JSON: ' + JSON.stringify(bant)).slice(0, 30000),
  first_name: parts.length > 1 ? parts[0] : '',
  last_name: parts.length > 1 ? parts.slice(1).join(' ') : (parts[0] || 'Голосовий лід'),
  company_final: r.company || c.company || 'Не вказано',
  bant_json: bant
} }];
